import json,re,glob,os,collections
rows={json.loads(l)['record_id']:json.loads(l) for l in open('logs/historical/pass_a/regrade.jsonl')}
recs={json.loads(l)['record_id']:json.loads(l) for l in open('corpus/records.jsonl')}
def files(rid):
    p=recs[rid].get('patch') or ''
    if not p: return []
    txt=open('corpus/'+p,errors='replace').read()
    return re.findall(r'^diff --git a/(\S+) b/',txt,re.M)
groups=collections.defaultdict(list)
for rid,r in rows.items():
    fs=files(rid)
    ec=[n for n in r['notes'] if n.startswith('exit')][0]
    if 'conftest.py' in fs: g='conftest'
    elif 'pytest.ini' in fs or any('rollout_report_plugin' in x for x in fs): g='pytest_ini_plugin'
    elif any((('/test' in x) or x.startswith('test')) and x.endswith(('.py','.md')) for x in fs): g='mod_testfile'
    elif not fs: g='empty/patch-failed'
    else: g='code_only'
    groups[g].append((rid,ec,fs))
for g,rs in groups.items():
    print('===',g,len(rs),collections.Counter(x[1] for x in rs))
    for rid,ec,fs in rs:
        if g!='conftest': print('   ',rid,ec,fs)
PY

