cd /tmp/analysis && cat > baseline.py <<'PY'
import json, os, re, subprocess, shutil, tempfile, time
from pathlib import Path
from concurrent.futures import ThreadPoolExecutor
WS=Path('/workspace')
man=[json.loads(l) for l in open(WS/'corpus/manifest.jsonl')]
STATUS=re.compile(r'^(?P<node>.+?)\s+(?P<st>PASSED|FAILED|ERROR|SKIPPED|XFAIL|XPASS)\s+\[')
def parse(log):
    out={}
    for line in log.splitlines():
        m=STATUS.match(line.strip())
        if m: out[m.group('node')]=m.group('st')
    return out
def run(row):
    scratch=Path(tempfile.mkdtemp(prefix='base_'))
    repo=scratch/row['repo_key']
    shutil.copytree(WS/'corpus/repos'/row['repo_root'].split('/')[-1], repo, symlinks=True)
    env=dict(os.environ, HOME='/tmp', PYTHONDONTWRITEBYTECODE='1', PYTHONHASHSEED='0'); env.pop('PYTHONPATH',None)
    subprocess.run(['git','reset','--hard','HEAD'],cwd=repo,env=env,stdout=subprocess.DEVNULL,stderr=subprocess.DEVNULL)
    subprocess.run(['git','clean','-qfd'],cwd=repo,env=env,stdout=subprocess.DEVNULL,stderr=subprocess.DEVNULL)
    (scratch/'bug.patch').write_text((WS/'corpus'/row['bug_patch']).read_text())
    ap=subprocess.run(['git','apply','--whitespace=nowarn',str(scratch/'bug.patch')],cwd=repo,env=env,stdout=subprocess.PIPE,stderr=subprocess.STDOUT,text=True)
    if ap.returncode!=0:
