import json, os, re, subprocess, shutil, tempfile, time
from pathlib import Path
from concurrent.futures import ThreadPoolExecutor
WS=Path('/workspace')
man={json.loads(l)['instance_id']:json.loads(l) for l in open(WS/'corpus/manifest.jsonl')}
recs=[json.loads(l) for l in open(WS/'corpus/records.jsonl')]
hist={json.loads(l)['record_id']:json.loads(l) for l in open(WS/'logs/historical/pass_a/regrade.jsonl')}
PROG=re.compile(r'^(?P<node>.+?)\s+(?P<st>PASSED|FAILED|ERROR|SKIPPED|XFAIL|XPASS)\s+\[')
def parse(log):
    out={}
    for line in log.splitlines():
        m=PROG.match(line.strip())
        if m: out[m.group('node')]=m.group('st')
    return out
def norm(n): return '.'.join(n.split('::')[1:])
def run(row):
    row_inst=man[row['instance_id']]; rid=row['record_id']
    scratch=Path(tempfile.mkdtemp(prefix='orc_'))
    repo=scratch/row_inst['repo_key']
    env=dict(os.environ, HOME='/tmp', PYTHONDONTWRITEBYTECODE='1', PYTHONHASHSEED='0'); env.pop('PYTHONPATH',None)
    def g(*a, **kw):
        return subprocess.run(['git',*a],cwd=repo,env=env,stdout=subprocess.PIPE,stderr=subprocess.STDOUT,text=True,**kw)
    shutil.copytree(WS/'corpus'/row_inst['repo_root'], repo, symlinks=True)
    g('reset','--hard','HEAD'); g('clean','-qfd')
    (scratch/'bug.patch').write_text((WS/'corpus'/row_inst['bug_patch']).read_text())
    if g('apply','--whitespace=nowarn',str(scratch/'bug.patch')).returncode!=0:
        return {'rid':rid,'inst':row['instance_id'],'stage':'bug-apply','label':hist[rid]['label'],'oracle':'unscorable?','rc':None}
    apply_note='none'
    if row.get('patch'):
        ptxt=(WS/'corpus'/row['patch']).read_text()
        (scratch/'sub.patch').write_text(ptxt)
        ap=g('apply','--whitespace=nowarn',str(scratch/'sub.patch'))
        if ap.returncode!=0:
            ap2=subprocess.run(['patch','-p1','--forward','--batch','-i',str(scratch/'sub.patch')],cwd=repo,env=env,stdout=subprocess.PIPE,stderr=subprocess.STDOUT,text=True)
            apply_note='git-fail+patch-' + ('ok' if ap2.returncode==0 else 'fail')
        else: apply_note='ok'
    else:
        apply_note='empty'
    # --- proper exam restoration ---
    req=list(dict.fromkeys(row_inst.get('fail_to_pass',[])+row_inst.get('pass_to_pass',[])))
    files=list(dict.fromkeys(n.split('::')[0] for n in req))
    cfg={'conftest.py','pytest.ini','setup.cfg','pyproject.toml','tox.ini'}
    to_restore=set(files)
    # tracked config files anywhere
    tracked=g('ls-files').stdout.splitlines()
    for p in tracked:
        if os.path.basename(p) in cfg: to_restore.add(p)
    for p in to_restore:
        g('checkout','--',p)
    # remove untracked config/plugins/test files
    untracked=g('ls-files','--others','--exclude-standard').stdout.splitlines()
    removed=[]
    for p in untracked:
        b=os.path.basename(p)
        if b in cfg or b=='rollout_report_plugin.py' or b.startswith('test_') or b.endswith('_test.py'):
            try: (repo/p).unlink()
            except IsADirectoryError: pass
            removed.append(p)
    argv=[str(WS/'.venvs'/row_inst['repo_key']/'bin/python'),'-m','pytest','--disable-warnings','--color=no','--tb=no','--verbose',*files]
    try:
        cp=subprocess.run(argv,cwd=repo,env=env,stdout=subprocess.PIPE,stderr=subprocess.DEVNULL,text=True,timeout=40)
        log=cp.stdout; rc=cp.returncode; to=False
    except subprocess.TimeoutExpired as e:
        out=e.stdout or b''; log=out.decode(errors='replace') if isinstance(out,bytes) else out
        rc=-1; to=True
    st=parse(log)
    per={}; missing=[]; bad=[]
    for n in req:
        k=norm(n)
        if k in st:
            per[n]=st[k]
            if st[k]!='PASSED': bad.append((n,st[k]))
        else:
            sup=[(kk,vv) for kk,vv in st.items() if k in kk]
            if not sup:
                missing.append(n)
            elif all(v=='PASSED' for _,v in sup):
                per[n]='PASSED*'  # via superstring(s), all pass
            else:
                per[n]='AMBIG:'+','.join(sorted(set(v for _,v in sup)))
                bad.append((n,per[n]))
    resolved = (not to and rc==0 and not missing and not bad)
    return {'rid':rid,'inst':row['instance_id'],'apply':apply_note,'rc':rc,'timed_out':to,
            'nstat':len(st),'missing':missing[:8],'nmissing':len(missing),
            'bad':bad[:8],'nbad':len(bad),'resolved':resolved,
            'removed':removed[:5],'nremoved':len(removed),
            'hist_label':hist[rid]['label'],'hist_missing':len(hist[rid]['missing'])}
out=[]
with ThreadPoolExecutor(max_workers=8) as ex:
    for r in ex.map(run, recs): out.append(r)
json.dump(out, open('oracle.json','w'), indent=1)
from collections import Counter
print('total',len(out))
print('oracle resolved',sum(1 for r in out if r.get('resolved')))
print('apply',Counter(r.get('apply') for r in out))
print('timed out',sum(1 for r in out if r.get('timed_out')))
print('oracle resolved by hist label',Counter(r.get('hist_label') for r in out if r.get('resolved')))
for r in out:
    if r.get('resolved'): print('RESOLVED',r['rid'],'hist',r['hist_label'],'rc',r['rc'])
PY
